{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_or_mechanism",
      "facet": "mechanism",
      "statement": "When confronted with OR-connected terms, SQLite examines each OR term separately and tries to use an index to find the rowids associated with each term. It then takes the union of the resulting rowid sets.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_or_precondition",
      "facet": "precondition",
      "statement": "For the OR-by-UNION technique to be useful, there must be an index available that helps resolve every OR-connected term.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_or_fallback",
      "facet": "mechanism",
      "statement": "If even a single OR-connected term is not indexed, a full table scan would have to be done for that term, and a full table scan may be preferable to the union operation and follow-on searches.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_and_hypothesis",
      "facet": "other",
      "statement": "The OR-by-UNION technique could also be leveraged for AND-connected terms by using an intersect operator in place of union.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_and_status",
      "facet": "property",
      "statement": "The performance gain for AND-by-INTERSECT is slight, so SQLite does not implement that technique at this time.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_and_future",
      "facet": "other",
      "statement": "A future version might be enhanced to support AND-by-INTERSECT.",
      "start_line": 5,
      "end_line": 5
    }
  ],
  "claims": [],
  "questions": []
}
